  -- EE3-C1-S10 / EXPECTED
  ('6cb986a6-d88b-551a-83b5-7a11bfff431e', 'c7e1d5a7-26ce-5a17-8f17-5612e845801f', 'EXPECTED',
   'Cette fermeture du lundi me dérange beaucoup et je ne suis pas d''accord avec cette décision.',
