  -- EE3-C1-S11 / EXPECTED
  ('66997d3c-ceaa-5ce3-9170-eb1e21010e9f', 'b8a53428-729d-572e-b405-727920f426c4', 'EXPECTED',
   'Je préfère nettement voir un artisan boucher reprendre ce local plutôt qu''une grande enseigne.',
